276	    /**
277	     * Validate and normalize the optional owner email in place.
278	     *
279	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
280	     * When present it must be a syntactically valid address; a valid address is
281	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
282	     * present but syntactically invalid, so the caller can reject with 400.
283	     */
284	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
285	        String email = ownerFieldsDto.getEmail();
286	        if (email == null || email.isBlank()) {
287	            ownerFieldsDto.setEmail(null);
288	            return true;
289	        }
290	        String normalized = email.trim().toLowerCase(Locale.ROOT);
291	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
292	            return false;
293	        }
294	        // Reject addresses whose domain is on the disposable-domain blocklist.
295	        String domain = normalized.substring(normalized.indexOf('@') + 1);
296	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
297	            return false;
298	        }
299	        ownerFieldsDto.setEmail(normalized);
300	        return true;
301	    }
302	
303	    /**
304	     * Validate the optional owner postcode in place.
305	     *
306	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
307	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
308	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
309	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
310	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
311	     * when a postcode is present but malformed or out of range, so the caller can
312	     * reject with 400.
313	     */
314	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
315	        String postcode = ownerFieldsDto.getPostcode();
316	        if (postcode == null || postcode.isBlank()) {
317	            ownerFieldsDto.setPostcode(null);
318	            return true;
319	        }
320	        if (!postcode.matches("\\d{4}")) {
321	            return false;
322	        }
323	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
324	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
325	        if (range != null) {
326	            int value = Integer.parseInt(postcode);
327	            if (value < range[0] || value > range[1]) {
328	                return false;
329	            }
330	        }
331	        return true;
332	    }
