334	    /**
335	     * Validate and normalize the owner's address fields in place, preferring the structured
336	     * form over the flat 'address' for backward compatibility.
337	     *
338	     * <p>When a non-blank {@code addressLine1} is supplied it is the structured form: both
339	     * {@code addressLine1} and (when present) {@code addressLine2} are normalized and stored
340	     * back, and {@code address} is set to the composed value — the normalized addressLine1,
341	     * with a single space and the normalized addressLine2 appended when addressLine2 is present.
342	     * Otherwise the flat {@code address} is normalized in place and the structured lines are
343	     * cleared. Returns {@code false} when no address is supplied in either form (both the
344	     * structured addressLine1 and the flat address are blank once normalized), so the caller
345	     * can reject with 400.
346	     */
347	    private boolean normalizeAddresses(OwnerFieldsDto ownerFieldsDto) {
348	        String rawLine1 = ownerFieldsDto.getAddressLine1();
349	        if (rawLine1 != null && !rawLine1.isBlank()) {
350	            String line1 = normalizeAddress(rawLine1);
351	            if (line1.isBlank()) {
352	                return false;
353	            }
354	            ownerFieldsDto.setAddressLine1(line1);
355	            String rawLine2 = ownerFieldsDto.getAddressLine2();
356	            String composed = line1;
357	            if (rawLine2 != null && !rawLine2.isBlank()) {
358	                String line2 = normalizeAddress(rawLine2);
359	                ownerFieldsDto.setAddressLine2(line2);
360	                composed = line1 + " " + line2;
361	            }
362	            else {
363	                ownerFieldsDto.setAddressLine2(null);
364	            }
365	            ownerFieldsDto.setAddress(composed);
366	            return true;
367	        }
368	        // No structured address: fall back to the flat 'address' input.
369	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
370	        if (canonicalAddress.isBlank()) {
371	            return false;
372	        }
373	        ownerFieldsDto.setAddress(canonicalAddress);
374	        ownerFieldsDto.setAddressLine1(null);
375	        ownerFieldsDto.setAddressLine2(null);
376	        return true;
377	    }
