379	    /**
380	     * Normalize an owner address: trim, collapse each run of whitespace to a single
381	     * space, upper-case, and expand common street-type abbreviations
382	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
383	     * A {@code null} value normalizes to the empty string.
384	     */
385	    private static String normalizeAddress(String value) {
386	        if (value == null) {
387	            return "";
388	        }
389	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
390	        if (collapsed.isEmpty()) {
391	            return "";
392	        }
393	        String[] tokens = collapsed.split(" ");
394	        StringBuilder sb = new StringBuilder(collapsed.length());
395	        for (int i = 0; i < tokens.length; i++) {
396	            if (i > 0) {
397	                sb.append(' ');
398	            }
399	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
400	        }
401	        return sb.toString();
402	    }
