404	    /**
405	     * The contact portion of an owner's derived identity key: its normalized telephone and
406	     * email ('&lt;normalizedTelephone&gt;|&lt;email or empty&gt;'), i.e. the identity key
407	     * without the household segment. Two owners share an identity when this value is equal;
408	     * because the telephone is part of it, members of one household with different telephones
409	     * do not collide. A {@code null} email contributes the empty string.
410	     */
411	    private static String identityContact(Owner owner) {
412	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
413	        String email = owner.getEmail() == null ? "" : owner.getEmail();
414	        return telephone + "|" + email;
415	    }
