417	    /**
418	     * Normalize a telephone number to E.164 form.
419	     *
420	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
421	     * explicit leading {@code '+'} and country code it is kept; otherwise the
422	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
423	     * dropped from the national digits. The result must contain 8 to 15 digits
424	     * after the {@code '+'}, and — for a recognised country calling code — exactly
425	     * the national-number length that code mandates ({@code '+61'} => 9 national
426	     * digits, {@code '+1'} => 10).
427	     *
428	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
429	     *         the input is absent or cannot form a valid E.164 number.
430	     */
431	    private static String toE164(String raw) {
432	        if (raw == null) {
433	            return null;
434	        }
435	        String trimmed = raw.trim();
436	        boolean hasCountryCode = trimmed.startsWith("+");
437	        // Strip spaces, dashes and brackets.
438	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
439	        String digits;
440	        if (hasCountryCode) {
441	            // Keep the explicit country code; drop the leading '+' for validation.
442	            digits = stripped.substring(1);
443	        } else {
444	            // No country code: assume '+61' and drop a single leading '0'.
445	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
446	            digits = "61" + national;
447	        }
448	        if (!digits.matches("\\d{8,15}")) {
449	            return null;
450	        }
451	        // For a recognised country calling code, enforce the exact national-number length it
452	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
453	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
454	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
455	                .sorted((a, b) -> b.length() - a.length()).toList()) {
456	            if (digits.startsWith(countryCode)) {
457	                int nationalLength = digits.length() - countryCode.length();
458	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
459	                    return null;
460	                }
461	                break;
462	            }
463	        }
464	        return "+" + digits;
465	    }
