481	    /**
482	     * Count the existing owners in the same household as the given owner, i.e. those sharing its
483	     * computed householdId (derived from the normalized last name and postcode). Used, together
484	     * with the owner being created, to derive the household size recorded on the owner.
485	     */
486	    private int countHouseholdMembers(Owner owner) {
487	        String householdId = ownerMapper.householdId(owner);
488	        return (int) this.clinicService.findAllOwners().stream()
489	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
490	            .count();
