493	    /**
494	     * Find an existing owner that the given (not-yet-created) owner is a possible (soft) duplicate
495	     * of: one sharing the same last name (compared case-insensitively) and the same postcode, but
496	     * carrying a different normalized telephone. Owners without a postcode never match (the postcode
497	     * must be shared). When several existing owners match, the one with the lowest id is returned so
498	     * the result is deterministic. Returns {@code null} when there is no such match.
499	     */
500	    private Owner findPossibleDuplicate(Owner candidate) {
501	        if (candidate.getPostcode() == null) {
502	            return null;
503	        }
504	        return this.clinicService.findAllOwners().stream()
505	            .filter(existing -> existing.getLastName() != null
506	                && existing.getLastName().equalsIgnoreCase(candidate.getLastName())
507	                && candidate.getPostcode().equals(existing.getPostcode())
508	                && !candidate.getTelephone().equals(existing.getTelephone()))
509	            .min(java.util.Comparator.comparing(Owner::getId))
510	            .orElse(null);
511	    }
