513	    /**
514	     * Build the owner's customer code, formatted {@code '<REGION>-<HASH8>'}.
515	     *
516	     * <p>{@code REGION} is the region derived from the owner's postcode (see
517	     * {@link #deriveRegion}). {@code HASH8} is the first 8 upper-case hex characters of the
518	     * SHA-256 of the normalized telephone concatenated with the last name
519	     * (e.g. {@code 'NSW-1A2B3C4D'}).
520	     *
521	     * <p>When the computed code collides with an existing owner's customer code, it is
522	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more
523	     * that makes it unique.
524	     */
525	    private String customerCode(Owner owner) {
526	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
527	        String hash8 = sha256HexUpper(owner.getTelephone() + owner.getLastName(), 8);
528	        String base = region + "-" + hash8;
529	        Set<String> existing = this.clinicService.findAllOwners().stream()
530	            .map(Owner::getCustomerCode)
531	            .filter(java.util.Objects::nonNull)
532	            .collect(Collectors.toSet());
533	        if (!existing.contains(base)) {
534	            return base;
535	        }
536	        int n = 2;
537	        while (existing.contains(base + "-" + n)) {
538	            n++;
539	        }
540	        return base + "-" + n;
541	    }
542	
543	    /**
544	     * Derive the owner's region, preferring the postcode. The postcode is matched against
545	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
546	     * it is absent or in no known range does this fall back to the fixed city-to-region table
547	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
548	     */
549	    private static String deriveRegion(String postcode, String city) {
550	        if (postcode != null && postcode.matches("\\d{4}")) {
551	            int value = Integer.parseInt(postcode);
552	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
553	                int[] range = entry.getValue();
554	                if (value >= range[0] && value <= range[1]) {
555	                    return entry.getKey();
556	                }
557	            }
558	        }
559	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
560	    }
561	
562	    /**
563	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
564	     * bytes of {@code value}.
565	     */
566	    private static String sha256HexUpper(String value, int length) {
567	        try {
568	            byte[] digest = MessageDigest.getInstance("SHA-256")
569	                .digest(value.getBytes(StandardCharsets.UTF_8));
570	            StringBuilder sb = new StringBuilder(digest.length * 2);
571	            for (byte b : digest) {
572	                sb.append(String.format("%02X", b));
573	            }
574	            return sb.substring(0, length);
575	        }
576	        catch (NoSuchAlgorithmException e) {
577	            throw new IllegalStateException(e);
578	        }
579	    }
