602	    /**
603	     * Roll a registration date forward onto a business day: a Saturday or Sunday is moved to
604	     * the following Monday; a weekday is returned unchanged.
605	     */
606	    private static LocalDate toBusinessDay(LocalDate date) {
607	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
608	            || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
609	            date = date.plusDays(1);
610	        }
611	        return date;
612	    }
