616	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
617	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
618	        if (currentOwner == null) {
619	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
620	        }
621	        if (!normalizeEmail(ownerFieldsDto)) {
622	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
623	        }
624	        if (!normalizePostcode(ownerFieldsDto)) {
625	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
626	        }
627	        if (!normalizeAddresses(ownerFieldsDto)) {
628	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
629	        }
630	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
631	        if (normalizedTelephone == null) {
632	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
633	        }
634	        currentOwner.setAddress(ownerFieldsDto.getAddress());
635	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
636	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
637	        currentOwner.setCity(ownerFieldsDto.getCity());
638	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
639	        currentOwner.setLastName(ownerFieldsDto.getLastName());
640	        currentOwner.setTelephone(normalizedTelephone);
641	        currentOwner.setEmail(ownerFieldsDto.getEmail());
642	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
643	        this.clinicService.saveOwner(currentOwner);
644	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
645	    }
